import itertools
strings=[line.rstrip('\n') for line in open('deploy.log') if line.startswith('#') or line.startswith('ERROR')]
print([len(s) for s in strings])
# shortest superstring by brute permutations of 4
best=sum(map(len,strings)); bestp=None
for p in itertools.permutations(strings):
    s=p[0]
    for t in p[1:]:
        # max overlap suffix of s prefix of t
        maxo=0
        for o in range(min(len(s),len(t)),0,-1):
            if s[-o:]==t[:o]:
                maxo=o;break
        s += t[maxo:]
    if len(s)<best:
        best=len(s); bestp=p
print(best,bestp)
for p in [bestp]:
    s=p[0]
    for t in p[1:]:
        maxo=0
        for o in range(min(len(s),len(t)),0,-1):
            if s[-o:]==t[:o]:
                maxo=o;break
        s += t[maxo:]
    print(len(s),repr(s))
